/* Campus discovery uses public evidence and optional device preferences. No profile is uploaded. */
(function(root,factory){'use strict';const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else{root.DegreeCampusDiscovery=api;if(root.document)api.mount(root);}}(typeof globalThis!=='undefined'?globalThis:this,function(){
 'use strict';
 const list=v=>Array.isArray(v)?v:[],text=v=>typeof v==='string'?v.trim():'',key=v=>text(v).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,''),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const traitLabels={sports:'Division I sports',housing:'Campus housing',city:'City setting',faith:'Faith-based community','small-campus':'Smaller campus'};
 const stateNames={AL:'Alabama',AK:'Alaska',AZ:'Arizona',AR:'Arkansas',CA:'California',CO:'Colorado',CT:'Connecticut',DE:'Delaware',DC:'District of Columbia',FL:'Florida',GA:'Georgia',HI:'Hawaii',ID:'Idaho',IL:'Illinois',IN:'Indiana',IA:'Iowa',KS:'Kansas',KY:'Kentucky',LA:'Louisiana',ME:'Maine',MD:'Maryland',MA:'Massachusetts',MI:'Michigan',MN:'Minnesota',MS:'Mississippi',MO:'Missouri',MT:'Montana',NE:'Nebraska',NV:'Nevada',NH:'New Hampshire',NJ:'New Jersey',NM:'New Mexico',NY:'New York',NC:'North Carolina',ND:'North Dakota',OH:'Ohio',OK:'Oklahoma',OR:'Oregon',PA:'Pennsylvania',RI:'Rhode Island',SC:'South Carolina',SD:'South Dakota',TN:'Tennessee',TX:'Texas',UT:'Utah',VT:'Vermont',VA:'Virginia',WA:'Washington',WV:'West Virginia',WI:'Wisconsin',WY:'Wyoming'};
 function url(v){try{const u=new URL(v);return u.protocol==='https:'&&!u.username&&!u.password?u.href:'';}catch{return '';}}
 function supportedTraits(c){return list(c?.traits).filter(t=>traitLabels[t]&&url(c.traitEvidence?.[t]?.url));}
 function normalizeFacts(value){return list(value?.campuses).filter(c=>text(c.id)&&text(c.school)&&text(c.city)&&stateNames[c.state]&&list(c.sourceUrls).some(url)).map(c=>({...c,routeIds:list(c.routeIds).filter(id=>/^[A-Za-z0-9_-]{1,160}$/.test(id)),traits:supportedTraits(c)}));}
 function mappedRoutes(c,catalog,available){const ids=new Set(list(available).map(r=>r.id));return list(catalog?.pathways).filter(r=>list(c.routeIds).includes(r.id)&&ids.has(r.id)&&key(r.school)===key(c.school)&&list(r.modalities).includes('campus')&&!list(r.modalities).includes('online'));}
 function filterCampuses(campuses,{search='',state='',trait='',mappedOnly=false}={},catalog={},available=[],interests=[]){
  const q=key(search);return list(campuses).filter(c=>(!q||key([c.school,c.city,c.campus].join(' ')).includes(q))&&(!state||c.state===state)&&(!trait||supportedTraits(c).includes(trait))&&(!mappedOnly||mappedRoutes(c,catalog,available).length)).map((c,index)=>({c,index,score:list(interests).filter(t=>supportedTraits(c).includes(t)).length})).sort((a,b)=>b.score-a.score||a.index-b.index).map(x=>x.c);
 }
 function sourceAnchor(href,label,cls=''){return '<a'+(cls?' class="'+cls+'"':'')+' href="'+esc(href)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a>';}
 function cardHTML(c,catalog,available,checkedOn,{plansLoaded=true}={}){
  const routes=mappedRoutes(c,catalog,available),traits=supportedTraits(c),official=url(c.officialUrl)||url(c.sourceUrls[0]),research=url(c.degreeUrl);
  const badges=traits.slice(0,3).map(t=>sourceAnchor(url(c.traitEvidence[t].url),traitLabels[t])).join('');
  const plans=routes.length?'<details><summary>'+routes.length+' available course plan'+(routes.length===1?'':'s')+'</summary><ul>'+routes.map(r=>'<li><a href="/portal.html?usePlan='+encodeURIComponent(r.id)+'">'+esc(r.title)+'</a></li>').join('')+'</ul></details>':'';
  const action=routes.length?'<a class="campus-button" href="/portal.html?usePlan='+encodeURIComponent(routes[0].id)+'">Use a course plan</a>':sourceAnchor(official,'Explore this campus','campus-button');
  const campusQuery=text(c.campus)?'&amp;campus='+encodeURIComponent(text(c.campus).slice(0,160)):'';
  const researchAction=!routes.length&&research?'<a class="campus-link" href="/request-plan.html?source='+encodeURIComponent(research)+'&amp;format=campus'+campusQuery+'">Research this degree</a>':!routes.length?'<a class="campus-link" href="/request-plan.html?school='+encodeURIComponent(c.school)+'&amp;format=campus'+campusQuery+'">Research a degree here</a>':sourceAnchor(official,'Explore this campus','campus-link');
  return '<article class="campus-card" data-campus-id="'+esc(c.id)+'"><h2>'+esc(c.school)+'</h2><p class="campus-location">'+esc(c.city)+', '+esc(stateNames[c.state])+'</p><p class="campus-name">'+esc(c.campus||'Physical campus')+'</p>'+(badges?'<div class="campus-badges" aria-label="Sourced campus features">'+badges+'</div>':'')+(text(c.description)?'<p class="campus-description">'+esc(c.description)+'</p>':'')+plans+'<div class="campus-actions">'+action+researchAction+'</div><p class="campus-sources">'+sourceAnchor(official,'Campus source')+' · Checked '+esc(c.identityEvidence?.checkedOn||checkedOn||'date not listed')+(routes.length?'':plansLoaded?' · Campus discovery; a course plan has not been published here.':' · Degree-plan availability could not load.')+'</p></article>';
 }
 function preferences(storage){try{const p=JSON.parse(storage?.getItem('degreepath-guide-v3')||'null')?.profile;return {homeState:stateNames[p?.homeState]?p.homeState:'',nearHome:p?.campusLocation==='near-home',interests:list(p?.campusInterests).filter(t=>traitLabels[t])};}catch{return {homeState:'',nearHome:false,interests:[]};}}
 async function mount(root){
  const $=id=>root.document.getElementById(id);if(!$('campus-app'))return;
  let catalog={pathways:[]},available=[],facts={campuses:[]},campuses=[],plansLoaded=false,prefs={homeState:'',nearHome:false,interests:[]};
  try{prefs=preferences(root.localStorage);}catch{}
  function filters(){return {search:$('campus-search').value,state:$('campus-state').value,trait:$('campus-trait').value,mappedOnly:$('campus-mapped').checked};}
  function render(){const rows=filterCampuses(campuses,filters(),catalog,available,prefs.interests);$('campus-count').textContent=rows.length+' campus'+(rows.length===1?'':'es')+(plansLoaded?' · '+rows.reduce((sum,c)=>sum+mappedRoutes(c,catalog,available).length,0)+' available course plans':' · Course-plan availability could not load');$('campus-results').setAttribute('aria-busy','false');$('campus-results').innerHTML=rows.length?rows.map(c=>cardHTML(c,catalog,available,facts.checkedOn,{plansLoaded})).join(''):'<section class="campus-empty"><h2>No campuses match these filters yet.</h2><p>Try another state or campus feature. You can also research a degree at a school you already have in mind.</p><a class="campus-button campus-secondary" href="/request-plan.html">Build from a degree link</a></section>';}
  $('campus-filters').addEventListener('submit',e=>{e.preventDefault();render();});$('campus-filters').addEventListener('input',render);$('campus-filters').addEventListener('change',render);$('campus-clear').addEventListener('click',()=>{$('campus-filters').reset();$('campus-personal').hidden=true;render();});
  try{
   const response=await root.fetch('/data/campus-facts.json');if(!response.ok)throw Error('Campus details could not load. Your plan and preferences are unchanged.');facts=await response.json();campuses=normalizeFacts(facts);
   try{const result=await root.fetch('/data/pathways.json');if(result.ok&&root.DegreeProgramCatalog){catalog=await root.DegreeProgramCatalog.load(await result.json());available=root.DegreeProgramCatalog.availablePlans(catalog,[]);plansLoaded=true;}}catch{/* Discovery remains useful when the separate plan directory is unavailable. */}
   const states=[...new Set(campuses.map(c=>c.state))].sort((a,b)=>stateNames[a].localeCompare(stateNames[b]));$('campus-state').innerHTML='<option value="">Any state</option>'+states.map(s=>'<option value="'+s+'">'+esc(stateNames[s])+'</option>').join('');
   if(prefs.nearHome&&prefs.homeState){if(states.includes(prefs.homeState))$('campus-state').value=prefs.homeState;$('campus-personal').hidden=false;$('campus-personal').textContent=states.includes(prefs.homeState)?'Starting with campuses in '+stateNames[prefs.homeState]+', based on your preferences. This compares states, not distance from your home.':'Your preference is to stay near home in '+stateNames[prefs.homeState]+'. These are the campuses currently researched; use a degree link to explore another school.';}
   render();
  }catch(error){$('campus-error').hidden=false;$('campus-error').textContent=error.message;$('campus-count').textContent='Campus discovery is temporarily unavailable.';$('campus-results').setAttribute('aria-busy','false');}
 }
 return Object.freeze({normalizeFacts,supportedTraits,mappedRoutes,filterCampuses,cardHTML,preferences,mount,stateNames});
}));
